class_name ReplayLoot
extends RefCounted

var _rng := RandomNumberGenerator.new()
var _draw_count: int = 0

func start(seed_value: int) -> void:
    _rng.seed = seed_value
    _draw_count = 0

func next_item() -> String:
    var roll: int = _rng.randi_range(1, 100)
    _draw_count += 1
    if roll <= 60:
        return "common"
    if roll <= 90:
        return "rare"
    return "epic"

func snapshot() -> Dictionary:
    return {"rng_state": _rng.state, "draw_count": _draw_count}

func restore(saved: Dictionary) -> Error:
    if not saved.has("rng_state") or not saved.has("draw_count"):
        return ERR_INVALID_DATA
    if typeof(saved["rng_state"]) != TYPE_INT or typeof(saved["draw_count"]) != TYPE_INT:
        return ERR_INVALID_DATA
    if saved["draw_count"] < 0:
        return ERR_INVALID_DATA
    _rng.state = saved["rng_state"]
    _draw_count = saved["draw_count"]
    return OK
